import e from"fs/promises";import r from"path";async function t(t){if("infer"!==t.locales)return t.locales.filter((e=>e!==t.sourceLocale));try{return(await e.readdir(t.messagesDir)).filter((e=>e.endsWith(t.extension))).map((e=>r.basename(e,t.extension))).filter((e=>e!==t.sourceLocale))}catch{return[]}}export{t as default};
